def categorize_errors(errors):
    '''Summarize errors by kind and group; identify extreme error-share groups.'''
    if not errors:
        raise ValueError('errors must not be empty')
    counts_by_kind = {}
    counts_by_group = {}
    for e in errors:
        if 'kind' not in e or 'group' not in e:
            raise ValueError('each error needs kind and group')
        counts_by_kind[e['kind']] = counts_by_kind.get(e['kind'], 0) + 1
        counts_by_group[e['group']] = counts_by_group.get(e['group'], 0) + 1
    total = len(errors)
    share_by_group = {g: c / total for g, c in counts_by_group.items()}
    highest = max(share_by_group, key=lambda g: share_by_group[g])
    lowest = min(share_by_group, key=lambda g: share_by_group[g])
    return {
        'counts_by_kind': counts_by_kind,
        'counts_by_group': counts_by_group,
        'share_by_group': share_by_group,
        'extreme_groups': {
            'highest': highest,
            'lowest': lowest,
            'difference': float(share_by_group[highest] - share_by_group[lowest]),
        },
    }

def model_card_stub(metrics_by_group):
    '''Minimal model card stub naming the group with the lowest metric.'''
    worst = min(metrics_by_group, key=lambda g: metrics_by_group[g])
